'use strict';
const repoUI={snapshot:null,selection:null,experiment:null,proposal:null,loading:false,defaultTask:'',loadedSource:null};
const repoEl=id=>document.getElementById(id);
function repoMessage(text,error=false){repoEl('repo-status').textContent=text;repoEl('repo-status').classList.toggle('error',error);}
function repoSourceKey(){return JSON.stringify([repoEl('repo-source').value,repoEl('repo-source').value==='github'?repoEl('repo-url').value.trim():repoEl('repo-source').value==='local'?repoEl('repo-path').value.trim():'',repoEl('repo-source').value==='demo'?'':repoEl('repo-ref').value.trim()||'HEAD']);}
function invalidateRepository(sourceChanged=false){repoUI.selection=null;repoUI.experiment=null;repoUI.proposal=null;repoEl('repo-download-context').disabled=true;repoEl('repo-selected-count').textContent='—';repoEl('repo-latency').textContent='—';repoEl('repo-benchmark-output').hidden=true;repoEl('repo-patch-area').hidden=true;repoEl('repo-grid-method').textContent='Curation required';renderRepoGrid();repoMessage(sourceChanged?'Source settings changed. Load the repository before curating.':'Task or selector settings changed. Curate again before generating a patch.');repoBusy(repoUI.loading);}
function repoBusy(value){for(const id of ['repo-source','repo-url','repo-path','repo-ref','repo-task','repo-method','repo-threshold','repo-top-k','repo-generator'])repoEl(id).disabled=value;repoUI.loading=value;for(const id of ['repo-load','repo-curate','repo-benchmark'])repoEl(id).disabled=value;repoEl('repo-curate').disabled=value||!repoUI.snapshot||repoUI.loadedSource!==repoSourceKey()||repoEl('repo-task').value.trim().length<5;repoEl('repo-propose').disabled=value||!repoUI.selection||!repoUI.selection.selected.length;repoEl('repo-benchmark').disabled=value||!repoUI.snapshot?.demo||!repoUI.selection||!repoUI.selection.selected.length||repoEl('repo-task').value.trim()!==repoUI.defaultTask;}
async function repoAPI(action,data){const response=await fetch('/api/repository/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const value=await response.json();if(!response.ok)throw new Error(value.error||'Repository investigation failed.');return value;}
function showRepository(){for(const selector of ['.page-heading','.scenario-section','.workbench','.proof-strip'])$(selector).hidden=true;repoEl('repository-lab').hidden=false;repoEl('context-nav').classList.add('active');repoEl('workbench-nav').classList.remove('active');$('.breadcrumbs strong').textContent='Repository lab';window.location.hash='repository';if(!repoUI.snapshot&&!repoUI.loading)loadRepository();}
function hideRepository(){for(const selector of ['.page-heading','.scenario-section','.workbench','.proof-strip'])$(selector).hidden=false;repoEl('repository-lab').hidden=true;repoEl('context-nav').classList.remove('active');repoEl('workbench-nav').classList.add('active');$('.breadcrumbs strong').textContent='Security workbench';history.replaceState(null,'',location.pathname);}
function sourceFields(){const source=repoEl('repo-source').value;repoEl('repo-url-field').hidden=source!=='github';repoEl('repo-path-field').hidden=source!=='local';repoEl('repo-ref-field').hidden=source==='demo';repoEl('repo-source-note').textContent=source==='demo'?'Owned fixture · no model calls until you curate · no changes to your working copy':source==='github'?'Public repository · pinned to an immutable commit · no GitHub writes or downloaded code execution':'Committed snapshot only · common sensitive paths excluded · review coverage before sending context';}
async function loadRepository(){if(repoUI.loading)return;repoBusy(true);repoMessage('Loading an immutable source snapshot…');try{repoUI.snapshot=await repoAPI('load',{source:repoEl('repo-source').value,url:repoEl('repo-url').value.trim(),path:repoEl('repo-path').value.trim(),ref:repoEl('repo-ref').value.trim()||'HEAD'});repoUI.loadedSource=repoSourceKey();repoUI.defaultTask=repoUI.snapshot.default_task;repoEl('repo-download-context').disabled=true;repoEl('repo-task').value=repoUI.defaultTask;repoUI.selection=null;repoUI.experiment=null;repoUI.proposal=null;repoEl('repo-benchmark-output').hidden=true;repoEl('repo-patch-area').hidden=true;repoEl('repo-files-count').textContent=repoUI.snapshot.files.length;repoEl('repo-context-size').textContent='~'+repoUI.snapshot.estimated_tokens.toLocaleString();repoEl('repo-token-note').textContent='Estimated raw-source tokens';repoEl('repo-selected-count').textContent='—';repoEl('repo-latency').textContent='—';repoEl('repo-grid-method').textContent='Read-only snapshot';repoEl('repo-exclusions-title').textContent=`Snapshot ${repoUI.snapshot.revision.slice(0,12)} · ${repoUI.snapshot.excluded.length} excluded entries`;repoEl('repo-exclusions-content').textContent=`Source: ${repoUI.snapshot.source}\nSHA-256: ${repoUI.snapshot.fingerprint}\nEligible source: ${repoUI.snapshot.total_bytes.toLocaleString()} bytes\n\n`+repoUI.snapshot.excluded.map(e=>`${e.path}: ${e.reason}`).join('\n');renderRepoGrid();inspectRepoFile(repoUI.snapshot.files[0].path);repoMessage(`${repoUI.snapshot.files.length} complete eligible files loaded. Review the task, then run SubQ or the offline keyword baseline.`);}catch(error){repoMessage(error.message,true);}finally{repoBusy(false);}}
function renderRepoGrid(){if(!repoUI.snapshot)return;const scores=new Map((repoUI.selection?.files||[]).map(f=>[f.path,f]));repoEl('repo-file-grid').innerHTML=repoUI.snapshot.files.map(file=>{const result=scores.get(file.path);const parts=file.path.split('/');const basename=parts.pop();const score=result?(result.method==='subq'?`p = ${result.score.toFixed(2)}`:`terms ${result.score.toFixed(1)}`):`${file.lines} lines`;return `<button class="repo-tile ${result?(result.selected?'selected':'dropped'):''}" data-repo-file="${escapeHtml(file.path)}"><small>${escapeHtml(parts.join('/')||'/')}</small><strong>${escapeHtml(basename)}</strong><em>${escapeHtml(score)}</em></button>`;}).join('');repoEl('repo-file-grid').querySelectorAll('[data-repo-file]').forEach(button=>button.addEventListener('click',()=>inspectRepoFile(button.dataset.repoFile)));}
function inspectRepoFile(path){const file=repoUI.snapshot.files.find(f=>f.path===path);if(!file)return;repoEl('repo-file-name').textContent=file.path;repoEl('repo-file-content').textContent=file.content.split('\n').map((line,i)=>`${String(i+1).padStart(3)}  ${line}`).join('\n');const scored=repoUI.selection?.files.find(f=>f.path===path);repoEl('repo-range-note').textContent=scored?.line_ranges.length?'Keyword-guided inspection hints: '+scored.line_ranges.map(r=>`L${r.start}–${r.end}`).join(', ')+'. Full selected files remain available to the patch author.':'Complete source shown. No content was replaced by a filename summary.';}
async function curateRepository(){if(repoUI.loading||!repoUI.snapshot||repoUI.loadedSource!==repoSourceKey())return;repoBusy(true);repoMessage('Reading the task against every eligible file. Large snapshots may need multiple full-context calls…');try{repoUI.selection=await repoAPI('curate',{id:repoUI.snapshot.id,task:repoEl('repo-task').value.trim(),method:repoEl('repo-method').value,threshold:Number(repoEl('repo-threshold').value),top_k:Number(repoEl('repo-top-k').value)});repoUI.experiment=null;repoUI.proposal=null;repoEl('repo-benchmark-output').hidden=true;repoEl('repo-patch-area').hidden=true;const r=repoUI.selection;repoEl('repo-selected-count').textContent=`${r.selected.length} / ${r.file_count}`;repoEl('repo-latency').textContent=(r.latency_ms/1000).toFixed(2)+' s';repoEl('repo-context-size').textContent=(r.actual_input_tokens??r.estimated_context_tokens).toLocaleString();repoEl('repo-token-note').textContent=r.actual_input_tokens!==null?`Actual input tokens across ${r.model_calls} call(s)`:'Estimated numbered context; no model call';repoEl('repo-grid-method').textContent=r.method==='subq'?'SubQ yes/no probabilities':'Keyword scores · not probabilities';repoEl('repo-download-context').disabled=false;renderRepoGrid();if(r.selected[0])inspectRepoFile(r.selected[0]);repoMessage(`Selected files: ${r.selected.length}; ${(100*r.context_reduction).toFixed(1)}% less raw source for the patch author. Selector cost/time must also be counted. ${r.method==='subq'?'Every eligible file was included in full.':'This is a lexical baseline, not a model prediction.'}`);repoEl('repo-experiment-note').textContent=repoUI.snapshot.demo?'Run the frozen acceptance suite in isolated copies. No working checkout is modified.':'This GitHub/local snapshot is inspection-only. Use Atlas to measure end-to-end migration correctness.';}catch(error){repoMessage(error.message,true);}finally{repoBusy(false);}}
async function runMigration(){if(repoUI.loading||!repoUI.selection)return;repoBusy(true);repoMessage('Proposing multi-file changes in isolated copies, then running the same independent checks in each comparison arm…');try{repoUI.experiment=await repoAPI('benchmark',{id:repoUI.snapshot.id,selection_id:repoUI.selection.selection_id,generator:repoEl('repo-generator').value});const result=repoUI.experiment;repoEl('repo-benchmark-output').hidden=false;repoEl('repo-benchmark-output').innerHTML='<div class="repo-results">'+result.arms.map(arm=>`<article class="repo-arm"><h3>${escapeHtml(arm.label)}</h3><span class="arm-verdict ${arm.verdict==='PASS'?'pass':''}">${escapeHtml(arm.verdict)}</span><strong>${arm.passed} / ${arm.total}</strong><p>Independent acceptance checks passed<br>${arm.selected.length} selected files · ${(arm.recall*100).toFixed(0)}% required-file recall<br>Patcher: ${escapeHtml(arm.generator)}</p>${arm.error?`<p>${escapeHtml(arm.error)}</p>`:''}<details><summary>Inspect checks and missed files</summary><ul>${arm.checks.map(c=>`<li class="${c.passed?'':'check-failed'}">${c.passed?'PASS':'FAIL'} · ${escapeHtml(c.name)}${c.error?' — '+escapeHtml(c.error):''}</li>`).join('')}${arm.missed_files.map(p=>`<li class="check-failed">Missing context: ${escapeHtml(p)}</li>`).join('')}</ul></details></article>`).join('')+'</div><p class="repo-result-note">'+escapeHtml(result.comparison_note)+'<br>Frozen contract: '+escapeHtml(result.contract_hash.slice(0,20))+' · '+escapeHtml(result.scope)+'</p>';const first=result.arms[0];repoEl('repo-patch-area').hidden=!first.diff;repoEl('repo-patch').textContent=first.diff||'';repoMessage(`Experiment complete. ${first.label}: ${first.verdict}, ${first.passed}/${first.total} checks. These results describe this fixture and run, not a general coding benchmark.`);}catch(error){repoMessage(error.message,true);}finally{repoBusy(false);}}
function repoDownload(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
repoEl('context-nav').addEventListener('click',showRepository);repoEl('workbench-nav').addEventListener('click',hideRepository);repoEl('ledger-nav').addEventListener('click',hideRepository);repoEl('repo-source').addEventListener('change',()=>{sourceFields();invalidateRepository(true);});for(const id of ['repo-url','repo-path','repo-ref'])repoEl(id).addEventListener('input',()=>invalidateRepository(true));for(const id of ['repo-method','repo-threshold','repo-top-k'])repoEl(id).addEventListener('change',()=>invalidateRepository());repoEl('repo-load').addEventListener('click',loadRepository);repoEl('repo-curate').addEventListener('click',curateRepository);repoEl('repo-benchmark').addEventListener('click',runMigration);repoEl('repo-task').addEventListener('input',()=>invalidateRepository());repoEl('repo-download-patch').addEventListener('click',()=>{const diff=repoUI.proposal?.diff||repoUI.experiment?.arms[0].diff;if(diff)repoDownload('blindspot-proposed-change.patch',diff);});repoEl('repo-download-context').addEventListener('click',()=>{if(!repoUI.selection)return;const source=repoUI.selection.selected.map(p=>`[FILE ${p}]\n${repoUI.snapshot.files.find(f=>f.path===p).content}`).join('\n\n');repoDownload('blindspot-selected-context.txt','[TASK]\n'+repoUI.selection.task+'\n\n'+source);});
if(location.hash==='#repository')showRepository();

repoEl('repo-propose').addEventListener('click',async()=>{if(repoUI.loading||!repoUI.selection)return;repoBusy(true);repoMessage('Meta is drafting a patch from the selected source. It will not be applied or executed.');try{repoUI.proposal=await repoAPI('propose',{id:repoUI.snapshot.id,selection_id:repoUI.selection.selection_id});repoEl('repo-patch-area').hidden=false;repoEl('repo-patch').textContent=repoUI.proposal.diff;repoMessage('UNVERIFIED draft · changed files: '+repoUI.proposal.changed_files.length+'. Review and test this patch before applying it. No source changes were made.');}catch(error){repoMessage(error.message,true);}finally{repoBusy(false);}});
